-- Version 1. Additive migration. Existing accounts and samrit_record remain intact.
CREATE SCHEMA IF NOT EXISTS identity;
CREATE SCHEMA IF NOT EXISTS directory;
CREATE SCHEMA IF NOT EXISTS food;
CREATE SCHEMA IF NOT EXISTS logistics;
CREATE SCHEMA IF NOT EXISTS evidence;
CREATE SCHEMA IF NOT EXISTS feedback;
CREATE SCHEMA IF NOT EXISTS audit;
CREATE SCHEMA IF NOT EXISTS app;
CREATE OR REPLACE FUNCTION app.valid_metadata(value jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT jsonb_typeof(value) = 'object' AND octet_length(value::text) <= 16384 $$;

CREATE TABLE identity.organizations (
 id uuid PRIMARY KEY, name text NOT NULL, organization_type text NOT NULL CHECK(organization_type IN ('central_ngo','donor','center')),
 owner_id uuid REFERENCES public."user"(id) ON DELETE RESTRICT, metadata jsonb NOT NULL DEFAULT '{}' CHECK(app.valid_metadata(metadata)), created_at timestamptz NOT NULL DEFAULT now()
);
INSERT INTO identity.organizations(id,name,organization_type) VALUES('10000000-0000-4000-8000-000000000001','Samrit Central NGO','central_ngo');
CREATE TABLE identity.memberships (organization_id uuid REFERENCES identity.organizations(id) ON DELETE CASCADE, user_id uuid REFERENCES public."user"(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('ADMIN','DONOR','NGO','VOLUNTEER')), PRIMARY KEY(organization_id,user_id));
CREATE TABLE identity.driver_profiles (user_id uuid PRIMARY KEY REFERENCES public."user"(id) ON DELETE CASCADE, organization_id uuid NOT NULL REFERENCES identity.organizations(id), metadata jsonb NOT NULL DEFAULT '{}' CHECK(app.valid_metadata(metadata)));
CREATE VIEW identity.users AS SELECT id,email,name,role,"isActive","isVerified","createdAt" FROM public."user";
CREATE OR REPLACE FUNCTION identity.sync_membership() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE org uuid;
BEGIN
 IF NEW.role::text IN ('ADMIN','VOLUNTEER') THEN org := '10000000-0000-4000-8000-000000000001';
 ELSE org := NEW.id; INSERT INTO identity.organizations(id,name,organization_type,owner_id) VALUES(org,coalesce(NEW."organizationName",NEW.name),CASE WHEN NEW.role::text='DONOR' THEN 'donor' ELSE 'center' END,NEW.id) ON CONFLICT(id) DO UPDATE SET name=EXCLUDED.name; END IF;
 INSERT INTO identity.memberships VALUES(org,NEW.id,NEW.role::text) ON CONFLICT(organization_id,user_id) DO UPDATE SET role=EXCLUDED.role;
 IF NEW.role::text='VOLUNTEER' THEN INSERT INTO identity.driver_profiles(user_id,organization_id) VALUES(NEW.id,org) ON CONFLICT DO NOTHING; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER user_membership AFTER INSERT OR UPDATE OF role,name,"organizationName" ON public."user" FOR EACH ROW EXECUTE FUNCTION identity.sync_membership();
-- Execute the trigger once for existing users without changing their credentials.
UPDATE public."user" SET name=name;

CREATE TABLE audit.data_sources(id uuid PRIMARY KEY, name text NOT NULL, url text NOT NULL UNIQUE, license_notes text NOT NULL, retrieved_at timestamptz NOT NULL, source_updated_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}' CHECK(app.valid_metadata(metadata)));
CREATE TABLE audit.import_runs(id uuid PRIMARY KEY, source_id uuid NOT NULL REFERENCES audit.data_sources, started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, status text NOT NULL CHECK(status IN ('running','completed','failed')), accepted_count integer NOT NULL DEFAULT 0 CHECK(accepted_count>=0), rejected_count integer NOT NULL DEFAULT 0 CHECK(rejected_count>=0), input_sha256 text, error_message text);
CREATE TABLE audit.source_records(id uuid PRIMARY KEY, source_id uuid NOT NULL REFERENCES audit.data_sources, external_id text NOT NULL, import_run_id uuid NOT NULL REFERENCES audit.import_runs, source_url text NOT NULL, content_sha256 text NOT NULL, raw_record jsonb NOT NULL, retrieved_at timestamptz NOT NULL, UNIQUE(source_id,external_id));
CREATE TABLE audit.organization_statistics(id uuid PRIMARY KEY, source_id uuid NOT NULL REFERENCES audit.data_sources, organization_name text NOT NULL, metric text NOT NULL, value numeric NOT NULL CHECK(value>=0), unit text NOT NULL, as_of date NOT NULL, source_page text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}' CHECK(app.valid_metadata(metadata)), UNIQUE(source_id,organization_name,metric,as_of));
CREATE TABLE app.domain_records(id uuid PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('event','center','batch','vehicle','route','photo','scan','review','driver_location')), actor_id uuid REFERENCES public."user"(id) ON DELETE RESTRICT, data_class text NOT NULL DEFAULT 'operational' CHECK(data_class IN ('operational','demo')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX domain_kind_created ON app.domain_records(kind,created_at DESC);
CREATE TABLE audit.audit_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, record_id uuid, actor_id uuid REFERENCES public."user"(id) ON DELETE SET NULL, action text NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), metadata jsonb NOT NULL DEFAULT '{}' CHECK(app.valid_metadata(metadata)));
CREATE INDEX audit_events_record_time ON audit.audit_events(record_id,occurred_at DESC);
CREATE TABLE directory.providers(id uuid PRIMARY KEY, name text NOT NULL, organization_id uuid REFERENCES identity.organizations, data_class text NOT NULL CHECK(data_class IN ('public_directory','demo','operational')), partner_verified boolean NOT NULL DEFAULT false, website text, phone text, source_record_id uuid REFERENCES audit.source_records, metadata jsonb NOT NULL DEFAULT '{}' CHECK(app.valid_metadata(metadata)));
CREATE TABLE directory.locations(id uuid PRIMARY KEY, provider_id uuid REFERENCES directory.providers ON DELETE CASCADE, address text NOT NULL, borough text, postal_code text, latitude double precision CHECK(latitude BETWEEN -90 AND 90), longitude double precision CHECK(longitude BETWEEN -180 AND 180), timezone text NOT NULL DEFAULT 'America/New_York', coordinate_source text, metadata jsonb NOT NULL DEFAULT '{}' CHECK(app.valid_metadata(metadata)), CHECK((latitude IS NULL)=(longitude IS NULL)));
CREATE INDEX location_lat_lng ON directory.locations(latitude,longitude);
CREATE TABLE directory.services(id uuid PRIMARY KEY, location_id uuid NOT NULL REFERENCES directory.locations ON DELETE CASCADE, service_type text NOT NULL CHECK(service_type IN ('soup_kitchen','food_pantry','food_distribution','community_center','unknown')), description text, eligibility text, verification_status text NOT NULL DEFAULT 'publicly_listed' CHECK(verification_status IN ('publicly_listed','operator_confirmed','unverified')), source_record_id uuid REFERENCES audit.source_records, metadata jsonb NOT NULL DEFAULT '{}' CHECK(app.valid_metadata(metadata)), UNIQUE(location_id,service_type));
CREATE TABLE directory.opening_hours(id uuid PRIMARY KEY, service_id uuid NOT NULL REFERENCES directory.services ON DELETE CASCADE, day_of_week smallint NOT NULL CHECK(day_of_week BETWEEN 0 AND 6), opens time NOT NULL, closes time NOT NULL, source_record_id uuid REFERENCES audit.source_records, verified_at timestamptz, CHECK(opens<>closes));
CREATE TABLE directory.service_exceptions(id uuid PRIMARY KEY, service_id uuid NOT NULL REFERENCES directory.services ON DELETE CASCADE, service_date date NOT NULL, closed boolean NOT NULL, note text NOT NULL, UNIQUE(service_id,service_date));
CREATE TABLE directory.partner_centers(id uuid PRIMARY KEY REFERENCES app.domain_records ON DELETE CASCADE, owner_id uuid NOT NULL REFERENCES public."user"(id), organization_id uuid NOT NULL REFERENCES identity.organizations, location_id uuid NOT NULL REFERENCES directory.locations, name text NOT NULL, refrigeration boolean NOT NULL, hot_holding boolean NOT NULL, freezer boolean NOT NULL, capacity_servings integer NOT NULL CHECK(capacity_servings>0), open_time time NOT NULL, close_time time NOT NULL, seating integer NOT NULL CHECK(seating>=0), staffing integer NOT NULL CHECK(staffing>0), qr_code text NOT NULL UNIQUE, approved boolean NOT NULL DEFAULT false, metadata jsonb NOT NULL DEFAULT '{}' CHECK(app.valid_metadata(metadata)), CHECK(open_time<>close_time));
CREATE TABLE food.donor_events(id uuid PRIMARY KEY REFERENCES app.domain_records ON DELETE CASCADE, donor_id uuid NOT NULL REFERENCES public."user"(id), organization_id uuid NOT NULL REFERENCES identity.organizations, location_id uuid NOT NULL REFERENCES directory.locations, name text NOT NULL, scheduled_at timestamptz NOT NULL, notes text NOT NULL DEFAULT '', metadata jsonb NOT NULL DEFAULT '{}' CHECK(app.valid_metadata(metadata)));
CREATE INDEX donor_event_owner_date ON food.donor_events(donor_id,scheduled_at DESC);
CREATE TABLE food.allergens(id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name text NOT NULL UNIQUE);
INSERT INTO food.allergens(name) VALUES('Milk'),('Eggs'),('Fish'),('Crustacean shellfish'),('Tree nuts'),('Peanuts'),('Wheat'),('Soybeans'),('Sesame');
CREATE TABLE food.ingredients(id uuid PRIMARY KEY, name text NOT NULL, normalized_name text NOT NULL UNIQUE);
CREATE TABLE food.menu_items(id uuid PRIMARY KEY, event_id uuid NOT NULL REFERENCES food.donor_events ON DELETE CASCADE, position integer NOT NULL CHECK(position>=0), name text NOT NULL, estimated_servings integer NOT NULL CHECK(estimated_servings>0), handling text NOT NULL CHECK(handling IN ('hot','refrigerated','frozen','shelf_stable')), verified boolean NOT NULL CHECK(verified), description text, metadata jsonb NOT NULL DEFAULT '{}' CHECK(app.valid_metadata(metadata)), UNIQUE(event_id,position));
CREATE TABLE food.menu_item_ingredients(menu_item_id uuid REFERENCES food.menu_items ON DELETE CASCADE, ingredient_id uuid REFERENCES food.ingredients, position integer NOT NULL, PRIMARY KEY(menu_item_id,ingredient_id));
CREATE TABLE food.menu_item_allergens(menu_item_id uuid REFERENCES food.menu_items ON DELETE CASCADE, allergen_id smallint REFERENCES food.allergens, PRIMARY KEY(menu_item_id,allergen_id));
CREATE TABLE evidence.photos(id uuid PRIMARY KEY REFERENCES app.domain_records ON DELETE CASCADE, actor_id uuid NOT NULL REFERENCES public."user"(id), stage smallint NOT NULL CHECK(stage BETWEEN 1 AND 3), batch_id uuid, url text NOT NULL, sha256 text NOT NULL CHECK(length(sha256)=64), latitude double precision NOT NULL CHECK(latitude BETWEEN -90 AND 90), longitude double precision NOT NULL CHECK(longitude BETWEEN -180 AND 180), captured_at timestamptz NOT NULL, UNIQUE(url,sha256));
CREATE TABLE food.food_batches(id uuid PRIMARY KEY REFERENCES app.domain_records ON DELETE CASCADE, event_id uuid NOT NULL REFERENCES food.donor_events ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, donor_id uuid NOT NULL REFERENCES public."user"(id), location_id uuid NOT NULL REFERENCES directory.locations, status text NOT NULL CHECK(status IN ('pending','matched','in_transit','delivered','rejected')), handling text NOT NULL CHECK(handling IN ('hot','refrigerated','frozen','shelf_stable')), expires_at timestamptz NOT NULL, sticker_id text UNIQUE, center_id uuid REFERENCES directory.partner_centers DEFERRABLE INITIALLY DEFERRED, driver_id uuid REFERENCES identity.driver_profiles DEFERRABLE INITIALLY DEFERRED, donor_photo_id uuid NOT NULL REFERENCES evidence.photos DEFERRABLE INITIALLY DEFERRED, pickup_photo_id uuid REFERENCES evidence.photos DEFERRABLE INITIALLY DEFERRED, dropoff_photo_id uuid REFERENCES evidence.photos DEFERRABLE INITIALLY DEFERRED, rejection_reason text, metadata jsonb NOT NULL DEFAULT '{}' CHECK(app.valid_metadata(metadata)), CHECK(status NOT IN ('matched','in_transit','delivered') OR (center_id IS NOT NULL AND driver_id IS NOT NULL)), CHECK(status<>'delivered' OR dropoff_photo_id IS NOT NULL));
ALTER TABLE evidence.photos ADD CONSTRAINT photos_batch_fk FOREIGN KEY(batch_id) REFERENCES food.food_batches ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX pending_batch_expiry ON food.food_batches(expires_at) WHERE status='pending';
CREATE TABLE food.batch_items(batch_id uuid REFERENCES food.food_batches ON DELETE CASCADE, menu_item_id uuid REFERENCES food.menu_items ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED, servings integer NOT NULL CHECK(servings>0), PRIMARY KEY(batch_id,menu_item_id));
CREATE TABLE logistics.vehicles(id uuid PRIMARY KEY REFERENCES app.domain_records ON DELETE CASCADE, organization_id uuid NOT NULL REFERENCES identity.organizations, name text NOT NULL, registration text NOT NULL UNIQUE, capacity_servings integer NOT NULL CHECK(capacity_servings>0), status text NOT NULL CHECK(status IN ('ready','maintenance','inactive')), metadata jsonb NOT NULL DEFAULT '{}' CHECK(app.valid_metadata(metadata)));
CREATE TABLE logistics.equipment_types(id uuid PRIMARY KEY, name text NOT NULL UNIQUE);
CREATE TABLE logistics.vehicle_equipment(vehicle_id uuid REFERENCES logistics.vehicles ON DELETE CASCADE, equipment_type_id uuid REFERENCES logistics.equipment_types, PRIMARY KEY(vehicle_id,equipment_type_id));
CREATE TABLE logistics.vehicle_capabilities(vehicle_id uuid REFERENCES logistics.vehicles ON DELETE CASCADE, handling text CHECK(handling IN ('hot','refrigerated','frozen','shelf_stable')), PRIMARY KEY(vehicle_id,handling));
CREATE TABLE logistics.routes(id uuid PRIMARY KEY REFERENCES app.domain_records ON DELETE CASCADE, driver_id uuid NOT NULL REFERENCES identity.driver_profiles, vehicle_id uuid REFERENCES logistics.vehicles, center_id uuid NOT NULL REFERENCES directory.partner_centers, status text NOT NULL CHECK(status IN ('active','completed','cancelled')), distance_miles numeric NOT NULL CHECK(distance_miles>=0), estimated_minutes integer NOT NULL CHECK(estimated_minutes>=0), vehicle_snapshot jsonb, cancelled_at timestamptz, cancellation_reason text, metadata jsonb NOT NULL DEFAULT '{}' CHECK(app.valid_metadata(metadata)));
CREATE UNIQUE INDEX one_active_route_per_driver ON logistics.routes(driver_id) WHERE status='active';
CREATE UNIQUE INDEX one_active_route_per_vehicle ON logistics.routes(vehicle_id) WHERE status='active' AND vehicle_id IS NOT NULL;
CREATE TABLE logistics.route_batches(route_id uuid REFERENCES logistics.routes ON DELETE CASCADE, batch_id uuid REFERENCES food.food_batches ON DELETE CASCADE, PRIMARY KEY(route_id,batch_id));
CREATE TABLE logistics.route_stops(id uuid PRIMARY KEY, route_id uuid NOT NULL REFERENCES logistics.routes ON DELETE CASCADE, batch_id uuid NOT NULL REFERENCES food.food_batches ON DELETE CASCADE, location_id uuid NOT NULL REFERENCES directory.locations, position integer NOT NULL, stop_type text NOT NULL CHECK(stop_type IN ('pickup','dropoff')), status text NOT NULL CHECK(status IN ('pending','done')), UNIQUE(route_id,position));
CREATE VIEW logistics.resource_assignments AS SELECT id AS route_id,driver_id,vehicle_id,status FROM logistics.routes;
CREATE TABLE evidence.custody_events(id uuid PRIMARY KEY REFERENCES app.domain_records ON DELETE CASCADE, batch_id uuid NOT NULL REFERENCES food.food_batches ON DELETE CASCADE, actor_id uuid NOT NULL REFERENCES public."user"(id), event_type text NOT NULL CHECK(event_type IN ('event','sticker_link','center')), scanned_value text NOT NULL, latitude double precision NOT NULL CHECK(latitude BETWEEN -90 AND 90), longitude double precision NOT NULL CHECK(longitude BETWEEN -180 AND 180), occurred_at timestamptz NOT NULL);
CREATE TABLE evidence.location_reports(id uuid PRIMARY KEY REFERENCES app.domain_records ON DELETE CASCADE, driver_id uuid NOT NULL REFERENCES identity.driver_profiles, latitude double precision NOT NULL CHECK(latitude BETWEEN -90 AND 90), longitude double precision NOT NULL CHECK(longitude BETWEEN -180 AND 180), reported_at timestamptz NOT NULL, source text NOT NULL CHECK(source IN ('admin_base','driver_report','custody_scan')));
CREATE TABLE feedback.reviews(id uuid PRIMARY KEY REFERENCES app.domain_records ON DELETE CASCADE, author_id uuid NOT NULL REFERENCES public."user"(id), target_type text NOT NULL CHECK(target_type IN ('donor','center')), target_id uuid NOT NULL, donor_id uuid REFERENCES public."user"(id), center_id uuid REFERENCES directory.partner_centers, batch_id uuid NOT NULL REFERENCES food.food_batches ON DELETE CASCADE, sentiment text NOT NULL CHECK(sentiment IN ('positive','negative')), raw_text text NOT NULL, parsed_flags text[] NOT NULL DEFAULT '{}', analysis_mode text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}' CHECK(app.valid_metadata(metadata)), CHECK((target_type='donor' AND donor_id=target_id AND center_id IS NULL) OR (target_type='center' AND center_id=target_id AND donor_id IS NULL)));

CREATE TABLE food.meal_offers(id uuid PRIMARY KEY, location_id uuid NOT NULL REFERENCES directory.locations ON DELETE CASCADE, menu_item_id uuid REFERENCES food.menu_items, name text NOT NULL, description text NOT NULL, serving_temperature text NOT NULL CHECK(serving_temperature IN ('hot','cold','room_temperature','unknown')), dietary_tags text[] NOT NULL DEFAULT '{}', allergens text[] NOT NULL DEFAULT '{}', available_from timestamptz, available_until timestamptz, verified_by uuid REFERENCES public."user"(id), data_class text NOT NULL CHECK(data_class IN ('demo','operational')), metadata jsonb NOT NULL DEFAULT '{}' CHECK(app.valid_metadata(metadata)), CHECK(available_until IS NULL OR available_from IS NULL OR available_until>available_from));
CREATE TABLE app.ai_jobs(id uuid PRIMARY KEY, task text NOT NULL CHECK(task IN ('meal_filter','menu_ocr','invoice_ocr','feedback_analysis','review_analysis')), actor_id uuid REFERENCES public."user"(id) ON DELETE SET NULL, related_type text, related_id uuid, provider text NOT NULL DEFAULT 'gemini', model text NOT NULL, prompt_version text NOT NULL, input_sha256 text NOT NULL, status text NOT NULL CHECK(status IN ('running','completed','failed')), result jsonb, error_code text, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, CHECK(result IS NULL OR octet_length(result::text)<=100000));
CREATE INDEX ai_job_related ON app.ai_jobs(related_type,related_id,started_at DESC);
CREATE TABLE food.event_documents(id uuid PRIMARY KEY, event_id uuid REFERENCES food.donor_events ON DELETE SET NULL, uploader_id uuid NOT NULL REFERENCES public."user"(id), document_type text NOT NULL CHECK(document_type IN ('menu','invoice')), original_name text NOT NULL, storage_path text NOT NULL, mime_type text NOT NULL CHECK(mime_type IN ('image/png','image/jpeg','image/webp','application/pdf')), sha256 text NOT NULL CHECK(length(sha256)=64), byte_size integer NOT NULL CHECK(byte_size BETWEEN 1 AND 5242880), uploaded_at timestamptz NOT NULL DEFAULT now(), metadata jsonb NOT NULL DEFAULT '{}' CHECK(app.valid_metadata(metadata)));
CREATE TABLE food.document_extractions(id uuid PRIMARY KEY, document_id uuid NOT NULL REFERENCES food.event_documents ON DELETE CASCADE, job_id uuid REFERENCES app.ai_jobs, status text NOT NULL CHECK(status IN ('completed','failed')), extracted_at timestamptz NOT NULL DEFAULT now(), error_code text, metadata jsonb NOT NULL DEFAULT '{}' CHECK(app.valid_metadata(metadata)));
CREATE TABLE food.extracted_food_items(id uuid PRIMARY KEY, extraction_id uuid NOT NULL REFERENCES food.document_extractions ON DELETE CASCADE, name text NOT NULL, ingredients text[], allergens text[], quantity numeric CHECK(quantity>=0), unit text, estimated_servings integer CHECK(estimated_servings>0), handling text CHECK(handling IN ('hot','refrigerated','frozen','shelf_stable','unknown')), source_reference text, item_type text NOT NULL CHECK(item_type IN ('dish','ingredient','unknown')), confirmed boolean NOT NULL DEFAULT false, metadata jsonb NOT NULL DEFAULT '{}' CHECK(app.valid_metadata(metadata)));
CREATE TABLE food.document_item_links(candidate_id uuid REFERENCES food.extracted_food_items ON DELETE CASCADE, menu_item_id uuid REFERENCES food.menu_items ON DELETE CASCADE, confirmed_by uuid NOT NULL REFERENCES public."user"(id), confirmed_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(candidate_id,menu_item_id));
CREATE TABLE feedback.venue_qr_codes(id uuid PRIMARY KEY, location_id uuid NOT NULL REFERENCES directory.locations ON DELETE CASCADE, phase text NOT NULL CHECK(phase IN ('entry','exit')), token_hash text NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE feedback.visits(id uuid PRIMARY KEY, location_id uuid NOT NULL REFERENCES directory.locations, secret_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE feedback.visit_scans(id uuid PRIMARY KEY, visit_id uuid NOT NULL REFERENCES feedback.visits ON DELETE CASCADE, qr_code_id uuid NOT NULL REFERENCES feedback.venue_qr_codes, phase text NOT NULL CHECK(phase IN ('entry','exit')), server_recorded_at timestamptz NOT NULL DEFAULT now(), device_recorded_at timestamptz, latitude double precision CHECK(latitude BETWEEN -90 AND 90), longitude double precision CHECK(longitude BETWEEN -180 AND 180), accuracy_meters double precision CHECK(accuracy_meters>=0), capture_method text NOT NULL CHECK(capture_method IN ('camera','manual')), UNIQUE(visit_id,phase));
CREATE TABLE feedback.visit_reviews(id uuid PRIMARY KEY, visit_id uuid NOT NULL UNIQUE REFERENCES feedback.visits ON DELETE CASCADE, sentiment text NOT NULL CHECK(sentiment IN ('positive','negative')), raw_text text NOT NULL CHECK(length(raw_text)<=3000), created_at timestamptz NOT NULL DEFAULT now(), moderation_status text NOT NULL DEFAULT 'pending' CHECK(moderation_status IN ('pending','reviewed')), metadata jsonb NOT NULL DEFAULT '{}' CHECK(app.valid_metadata(metadata)));
CREATE TABLE feedback.review_analysis(id uuid PRIMARY KEY, visit_review_id uuid REFERENCES feedback.visit_reviews ON DELETE CASCADE, handoff_review_id uuid REFERENCES feedback.reviews ON DELETE CASCADE, job_id uuid REFERENCES app.ai_jobs, flags text[] NOT NULL DEFAULT '{}', summary text NOT NULL, consistency text NOT NULL, uncertainties text[] NOT NULL DEFAULT '{}', requires_human_review boolean NOT NULL DEFAULT true CHECK(requires_human_review), analysis_mode text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK((visit_review_id IS NULL)<>(handoff_review_id IS NULL)));
